    // Optional: scroll to result
    resultDiv.scrollIntoView({ behavior: 'smooth' });
});

function getFeedback(score, total) {
    const percentage = (score / total) * 100;
    if (percentage === 100) return "Perfect! You're a polyglot pro!";
