 document.getElementById('quiz-form').addEventListener('submit', function(e) {
     e.preventDefault();

     const answers = {
         q1: ['cpp', 'rust'],
         q2: ['rust', 'java'],
         q3: ['python', 'r']
     };

     let score = 0;
     const totalQuestions = Object.keys(answers).length;

     for (let q in answers) {
         const selectedOptions = Array.from(document.querySelectorAll(`input[name="${q}"]:checked`))
